web/interaction-finish.css:
/* Interaction finish, rc6. Only the owned home ShadowRoot and suite frontend.
   Keep this last in the assembly so motion/focus rules cannot regress via old layers. */
:host {--ui-fast:140ms;--ui-ease:cubic-bezier(.2,.7,.2,1);}
:host :is(button,input,select,textarea,a,summary):focus-visible {
 outline:2px solid var(--accent-strong);outline-offset:3px;
 box-shadow:0 0 0 2px var(--bg);scroll-margin-block:14px;
}
:host button:disabled{opacity:.6;cursor:default;}
:host :is(button[aria-pressed="true"],button[aria-current="page"]){font-weight:600;}
:host :is(.dialog-body,.side-scroll,.deck-picker,.context-menu){scroll-padding:12px;overscroll-behavior:contain;}
:host .context-menu {padding:8px;border-radius:14px;box-shadow:0 16px 48px var(--shadow),0 0 0 1px var(--line-soft);}
:host .context-action {min-height:40px;gap:10px;font-size:12px;}
:host .context-label {white-space:normal;overflow-wrap:anywhere;line-height:1.55;padding:9px 10px 12px;color:var(--muted);font-size:11px;max-height:64px;overflow:auto;}
:host .context-action:focus-visible{outline-offset:-3px;background:var(--raised);box-shadow:none;}
:host .dialog-header h2{font-family:var(--world-font);font-weight:500;line-height:1.2;}
:host .dialog-header p{font-size:12px;line-height:1.65;}
:host .dialog-footer{gap:10px;}
:host .dialog-alerts{flex-shrink:0;max-height:130px;overflow:auto;}
:host .dialog-alerts:empty{display:none;}
:host .dialog-alerts .toast{position:relative;inset:auto;transform:none;max-width:none;width:auto;margin:12px 20px 0;box-shadow:none;border:1px solid var(--line);border-left:3px solid var(--pink);}
:host .toast{overflow-wrap:anywhere;min-width:0;align-items:flex-start;background:var(--panel);border-color:var(--line);}
:host .toast>span{min-width:0;overflow-wrap:anywhere;}
:host .toast>.icon{margin-top:2px;}
:host .form-error:not(:empty){padding:12px;border:1px solid var(--line);border-left:3px solid var(--pink);border-radius:8px;background:var(--panel);color:var(--text);}
:host .empty{border-radius:var(--world-radius,16px);border:1px dashed var(--line);background:var(--panel);padding:30px 22px;}
:host .empty>svg{margin-inline:auto;color:var(--accent);}
:host .empty h3{font-family:var(--world-font);font-weight:500;line-height:1.3;}
:host .empty p{max-width:55ch;margin-inline:auto;line-height:1.7;}
:host .theme-check[hidden]{display:none!important;}
:host .switch{width:42px;height:26px;flex-basis:42px;}
:host .switch::after{width:18px;height:18px;top:3px;left:3px;}
:host .switch[aria-checked="true"]::after{left:19px;}
:host([data-motion="on"]) :is(.theme-tile,.context-action,.tool-tile,.lecture-study,.revisit-row button){transition:background-color var(--ui-fast) var(--ui-ease),border-color var(--ui-fast) var(--ui-ease),box-shadow var(--ui-fast) var(--ui-ease);}
/* No hover displacement on study/navigation targets. */
:host :is(.context-action,.theme-tile,.lecture-study,.tool-tile,.revisit-row button,.tree-row){transform:none!important;}
:host([data-ambience="false"]) :is(.app,.quiet-focus,.task-focus)::before,
:host([data-ambience="false"]) :is(.app,.quiet-focus,.task-focus)::after{content:none!important;background:none!important;}
:host([data-ambience="false"]) .main{background:var(--bg)!important;}
:host([data-ambience="false"]) .quiet-focus{background:var(--panel)!important;}
:host([data-motion="off"]) *, :host([data-motion="off"]) *::before, :host([data-motion="off"]) *::after{transition:none!important;animation:none!important;scroll-behavior:auto!important;}
#es-app[data-suite="true"]{--ui-fast:140ms;--ui-ease:cubic-bezier(.2,.7,.2,1);}
#es-app[data-suite="true"] :is(button,input,select,textarea,a,summary):focus-visible{outline:2px solid var(--es-accent);outline-offset:3px;box-shadow:0 0 0 2px var(--es-surface);scroll-margin-block:16px;}
#es-app[data-suite="true"] :is(button,input,select,textarea):disabled{cursor:default;}
#es-app[data-suite="true"] :is(.suite-modal-scroll,.suite-setup-scroll,.es-main){scroll-padding:18px;}
#es-app[data-suite="true"] :is(.es-toast,.es-error){overflow-wrap:anywhere;word-break:normal;line-height:1.65;}
#es-app[data-suite="true"] .suite-modal-alerts{flex-shrink:0;max-height:125px;overflow:auto;}
#es-app[data-suite="true"] .suite-modal-alerts .es-toast{margin:12px 20px 0;padding:12px 14px;border-left:3px solid var(--es-accent);box-shadow:none;color:var(--es-text);}
#es-app[data-suite="true"] :is(.es-helper,.es-disclosure,.es-note){line-height:1.65;}
#es-app[data-suite="true"] .es-top-nav button{transform:none!important;}
html[data-atelier-world-motion="false"] #es-app[data-suite="true"] *,html[data-atelier-world-motion="false"] #es-app[data-suite="true"] *::before,html[data-atelier-world-motion="false"] #es-app[data-suite="true"] *::after{transition:none!important;animation:none!important;scroll-behavior:auto!important;}
html[data-atelier-world-enabled="true"][data-atelier-scenery="false"] #es-app :is(.es-hero,.suite-result-hero){background-image:none!important;}
@media(prefers-reduced-motion:reduce){
 :host *, :host *::before, :host *::after,
 #es-app[data-suite="true"] *,#es-app[data-suite="true"] *::before,#es-app[data-suite="true"] *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;}
}
@media(forced-colors:active){
 :host :is(button,input,select,textarea,a,summary):focus-visible,
 #es-app[data-suite="true"] :is(button,input,select,textarea,a,summary):focus-visible{outline:2px solid Highlight;box-shadow:none!important;}
 :host :is(.theme-tile.selected,.tab.active,.nav-row.active),#es-app[data-suite="true"] [aria-current="page"]{outline:2px solid Highlight;outline-offset:-3px;}
 :host .theme-material-sample{border-color:ButtonText;}
}
@media(max-height:600px){:host .dialog-header{padding-top:15px;padding-bottom:12px;}:host .dialog-footer{padding-block:12px;}:host .dialog-alerts{max-height:85px;}}

:host .toast-dismiss{display:grid;place-items:center;flex:0 0 26px;width:26px;min-height:26px;border-radius:6px;color:var(--muted);margin-left:auto;}
:host .toast-dismiss:hover{background:var(--raised);color:var(--text);}
:host .toast>span{flex:1;}
